import torch

def check_classifier_batch(model, batch, device):
    """Validate an injected batch and model before optimization."""
    images = batch["image"].to(device, dtype=torch.float32)
    labels = batch["label"].to(device, dtype=torch.long)
    if images.ndim != 5 or images.shape[1] != 1:
        raise ValueError("expected images shaped [B, 1, D, H, W]")
    if not bool(torch.isfinite(images).all()):
        raise ValueError("images contain a non-finite value")
    if labels.shape != (images.shape[0],):
        raise ValueError("expected one class index per image")
    if not bool(((labels == 0) | (labels == 1)).all()):
        raise ValueError("labels must be 0 or 1")

    logits = model(images)
    if logits.shape != (images.shape[0], 2):
        raise ValueError("model must return two logits per image")
    if not bool(torch.isfinite(logits).all()):
        raise ValueError("logits contain a non-finite value")
    loss = torch.nn.functional.cross_entropy(logits, labels)
    if loss.ndim != 0:
        raise ValueError("loss must be scalar")
    return loss

import torch

def make_amp_scaler(device):
    return torch.amp.GradScaler(
        "cuda", enabled=device.type == "cuda",
    )

def amp_train_step(
    model, optimizer, loss_fn, scaler, images, labels,
):
    """Run one CUDA-float16 AMP step with injected state."""
    model.train()
    optimizer.zero_grad(set_to_none=True)
    use_amp = images.device.type == "cuda"
    with torch.autocast(
        device_type=images.device.type,
        dtype=torch.float16,
        enabled=use_amp,
    ):
        logits = model(images)
        loss = loss_fn(logits, labels)
    scaler.scale(loss).backward()
    scaler.step(optimizer)
    scaler.update()
    return loss.detach()

import torch

def load_training_checkpoint(
    checkpoint_path, model, optimizer, *, scheduler=None, scaler=None,
):
    """Load trusted plain state dictionaries into rebuilt objects."""
    checkpoint = torch.load(
        checkpoint_path,
        map_location="cpu",
        weights_only=True,
    )
    model.load_state_dict(checkpoint["model"])
    optimizer.load_state_dict(checkpoint["optimizer"])
    if scheduler is not None:
        scheduler.load_state_dict(checkpoint["scheduler"])
    if scaler is not None:
        scaler.load_state_dict(checkpoint["scaler"])
    start_epoch = int(checkpoint["epoch"]) + 1
    return start_epoch, checkpoint.get("best_validation")
